mapper.select:
SELECT order_id, user_id, acorn_amount, price, status, order_uid, created_at, updated_at
FROM orders
WHERE order_id = #{orderId}

mapper.update:
UPDATE orders SET status = #{toStatus}, updated_at = now()
WHERE order_id = #{orderId}
  AND status = #{fromStatus}

mapper.select:
SELECT wallet_id, user_id, balance, reserved_balance
FROM acorn_wallet
WHERE user_id = #{userId}

SELECT amount, balance_after, reason, created_at
FROM acorn_transaction
WHERE user_id = #{userId}
ORDER BY created_at DESC, acorn_tx_id DESC
LIMIT #{size} OFFSET #{offset}
